function loadTiming(){const src=between(front,"function unloadTiming","function isCompletedUnloadOverStandard");const ctx={Date,state:{standards:{"6W":45}},parseDate(v){if(!v)return null;const d=v instanceof Date?v:new Date(v);return Number.isNaN(d.getTime())?null:d},normalizeVehicle(){return "6W"},unloadStandard(){return 45},isDestination(){return true},confirmedEffectiveArrival(row){const route=this.parseDate(row.actualArrivalAt);if(!route)return null;return [row.actualArrivalAt,row.scheduleKitArrivalAt,row.scheduleTbrArrivalAt].map(v=>this.parseDate(v)).filter(Boolean).sort((a,b)=>a-b)[0]||null}};vm.createContext(ctx);vm.runInContext(src+";globalThis.fn=unloadTiming",ctx);return ctx.fn}
test("frozen upper metric markup and eight standalone classic lower cards",()=>{assert.equal((html.match(/class="metric-card/g)||[]).length,8);const r=between(front,"function renderFilterSummary(rows)","async function applyMetricFilter");assert.equal((r.match(/class="summary-card/g)||[]).length,8);assert.equal((r.match(/data-summary-status=/g)||[]).length,8);for(const key of ["all","waiting","unloading","completed","unload-overtime","origin","drop","cancelled"])assert.match(r,new RegExp(`data-summary-status="${key}"`));assert.doesNotMatch(r,/data-summary-substatus|summary-subfilter/);assert.match(r,/completedTodayOvertimeRows\(\)\.length/);assert.match(r,/queue\.cancelled && isCancelledToday\(row\)/)});
