test("arrival display requires Route confirmation then uses earliest Route KIT TBR",()=>{const schedule=between(front,"function scheduleSection(row, mode)","function queueInfo");assert.match(schedule,/\? confirmedEffectiveArrival\(row\)/);const src=between(front,"function effectiveArrival(row)","function attendanceLabel(row)");const ctx={parseDate(v){if(!v)return null;const d=new Date(v);return Number.isNaN(d.getTime())?null:d}};vm.createContext(ctx);vm.runInContext(src+";globalThis.fn=confirmedEffectiveArrival",ctx);assert.equal(ctx.fn({actualArrivalAt:"2026-09-09T09:09:00Z",scheduleKitArrivalAt:"2026-09-09T09:09:00Z",scheduleTbrArrivalAt:"2026-09-09T08:10:00Z"}).toISOString(),"2026-09-09T08:10:00.000Z");assert.equal(ctx.fn({scheduleKitArrivalAt:"2026-09-09T09:09:00Z",scheduleTbrArrivalAt:"2026-09-09T08:10:00Z"}),null)});
test("main arrival source detail hides Route but preserves confirmed effective truth",()=>{const sources=between(front,"function arrivalSources(row)","function arrivalSourceDateTime(value)");assert.doesNotMatch(sources,/<em>Route<\/em>/);assert.match(sources,/<em>KIT<\/em>/);assert.match(sources,/<em>TBR<\/em>/);assert.match(sources,/<em>ถึงจริงที่ใช้<\/em>/);assert.match(sources,/const effective = confirmedEffectiveArrival\(row\)/);assert.doesNotMatch(sources,/const earliest = \[row\.scheduleKitArrivalAt/)});
test("SLA Route uses earliest confirmed arrival while S E remains work duration",()=>{const fn=loadTiming();const t=fn({unloadingState:2,actualArrivalAt:"2026-09-08T15:56:00Z",scheduleKitArrivalAt:"2026-09-08T15:40:00Z",scheduleTbrArrivalAt:"2026-09-08T15:50:00Z",scheduleUnloadingStartedAt:"2026-09-08T18:01:00Z",unloadingCompletedAt:"2026-09-08T18:47:00Z"},new Date("2026-09-08T18:47:00Z"));assert.equal(t.slaMinutes,187);assert.equal(t.workMinutes,46);assert.equal(t.standard,45);assert.equal(t.overStandard,true);assert.equal(t.slaMinutes-t.standard,142)});
