test("work type labels are exact and mobile includes a non-duplicate subtitle",()=>{const labels=between(front,"function attendanceLabel(row)","function punctuality(row)");for(const text of ["ปลายทาง","ต้นทาง","จุดดรอป","รถเข้าคลัง","รถออกคลัง","ลงของและเดินทางต่อ"])assert.match(labels,new RegExp(text));assert.doesNotMatch(labels,/เข้า ·|ออก ·|ผ่าน ·/);const card=between(front,"function card(row)","let cancelRouteTarget");assert.match(card,/compact-work-type[\s\S]*type-badge[\s\S]*attendanceLabel\(row\)/)});
